import { useState, useEffect } from 'react';

const LightsIntro = ({ onComplete }) => {
  const [phase, setPhase] = useState('dark');

  useEffect(() => {
    if (phase === 'burst') {
      setTimeout(() => {
        setPhase('done');
        onComplete(); // 👈 tells Products.js to show products
      }, 1200);
    }
  }, [phase]);

  const ignite = () => setPhase('burst');

  if (phase === 'done') return null;

  return (
    <div style={{
      minHeight: '100vh', background: '#000',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      flexDirection: 'column', textAlign: 'center', padding: '0 24px',
      fontFamily: 'Poppins, sans-serif',
      backgroundImage: phase === 'burst'
        ? 'radial-gradient(ellipse at center, #ffdd4433 0%, #000 70%)'
        : 'none',
      transition: 'background-image 0.5s',
    }}>

      {phase === 'dark' && (
        <>
          <p style={{ color: '#444', letterSpacing: 6, fontSize: 11, marginBottom: 20, textTransform: 'uppercase' }}>
            wait · wait · wait
          </p>
          <h1 style={{ color: '#fff', fontSize: 'clamp(26px, 5vw, 44px)', fontWeight: 900, lineHeight: 1.25, marginBottom: 10 }}>
            Want to buy{' '}
            <span style={{ color: '#ffdd44', textShadow: '0 0 30px #ffdd4488' }}>light</span>
            <br />
            <span style={{ color: '#555' }}>to remove the</span>
            <br />
            darkness around you?
          </h1>
          <p style={{ color: '#555', fontSize: 13, letterSpacing: 2, marginBottom: 40 }}>
            we dare you to click this button
          </p>
          <button
            onClick={ignite}
            style={{
              border: '1px solid #ffdd44', background: 'transparent',
              color: '#ffdd44', padding: '14px 40px', fontSize: 12,
              letterSpacing: 4, fontWeight: 700, cursor: 'pointer',
              fontFamily: 'Poppins, sans-serif', textTransform: 'uppercase',
              transition: 'all 0.3s',
            }}
            onMouseEnter={e => { e.target.style.background='#ffdd44'; e.target.style.color='#000'; }}
            onMouseLeave={e => { e.target.style.background='transparent'; e.target.style.color='#ffdd44'; }}
          >
            TURN ON THE LIGHTS →
          </button>
        </>
      )}

      {phase === 'burst' && (
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontSize: 80, marginBottom: 20 }}>💡</div>
          <h2 style={{ color: '#ffdd44', fontSize: 32, fontWeight: 900, textShadow: '0 0 60px #ffdd44' }}>
            LET THERE BE LIGHT ✦
          </h2>
        </div>
      )}
    </div>
  );
};

export default LightsIntro;
